# --- import-time premises (re-derived, never transcribed) ------------
_P0 = 100000.0
_RD, _CP, _XLV = 287.0, 1004.5, 2.5e6
_SVP1, _SVP2, _SVP3, _SVPT0 = 0.6112, 17.67, 29.65, 273.15
_EP2 = 0.6217504


def _sat(th, qv, qc, p):
    """(membership on the registered qt >= qs test, theta_es) from the
    same Tetens-liquid constants gpuwm.verify.sase_ref.moist_n2 uses."""
    t = th * (p / _P0) ** (_RD / _CP)
    es = 1000.0 * _SVP1 * np.exp(_SVP2 * (t - _SVPT0) / (t - _SVP3))
    qs = _EP2 * es / (p - es)
    return (qv + qc) >= qs, th * np.exp(_XLV * qs / (_CP * t))


def _lowest_run(memb, min_cells=2):
    """The lowest contiguous run of >= min_cells member cells whose bulk
    theta_es reading is negative -- the authority's step 1."""
    k = 0
    while k < len(memb):
        if not memb[k]:
            k += 1
            continue
        s = k
        while k + 1 < len(memb) and memb[k + 1]:
            k += 1
        if k - s >= min_cells - 1:
            return s, k
        k += 1
    return None


def _peaks(thes):
    return [k for k in range(1, len(thes) - 1)
            if thes[k] > thes[k - 1] and thes[k] > thes[k + 1]]


for _pre in ("CLAMP", "DROP"):
    _th = globals()[_pre + "_THETA"]
    _qv, _qc = globals()[_pre + "_QV"], globals()[_pre + "_QC"]
    _pp, _tk = globals()[_pre + "_P"], globals()[_pre + "_THICK"]
    assert len(_th) == N_LEVELS and len(_tk) == N_LEVELS
    _memb, _thes = _sat(_th, _qv, _qc, _pp)
    _run = _lowest_run(_memb)
    assert _run is not None, (_pre, "must have a >=2-cell saturated run")
    _kb, _kt = _run
    assert _thes[_kt] < _thes[_kb], (_pre, "run must be moist-unstable")
    # THE BINDING PREMISE: the floor rejects every interior theta_es
    # maximum at or below the base, so the root falls back to the base.
    _floor = _kb - (_kt - _kb) - 1
    _elig = [k for k in _peaks(_thes) if k <= _kb]
    assert _elig, (_pre, "no interior peak at or below the base -- the "
                         "floor would have nothing to clamp")
    assert max(_elig) < _floor, (_pre, "the highest eligible peak is "
                                       "NOT below the floor", _elig,
                                 _floor)
    # ... and the frame's own turbulence is below the G-M5 floor, which
    # is why SURVEY_E and not *_E_FRAME sets the amplitude.
    assert globals()[_pre + "_E_FRAME"].max() < 0.5, _pre

_mc, _tc = _sat(CLAMP_THETA, CLAMP_QV, CLAMP_QC, CLAMP_P)
assert _lowest_run(_mc) == (20, 21), _lowest_run(_mc)
assert _peaks(_tc) == [15], _peaks(_tc)
# the minimum-run premise: the run is EXACTLY VENT_MIN_RUN_CELLS long,
# so raising the registered constant to 3 leaves the whole column with
# no qualifying run -- the guard, and only the guard, stands it down.
assert _lowest_run(_mc, 3) is None

_md, _td = _sat(DROP_THETA, DROP_QV, DROP_QC, DROP_P)
assert _lowest_run(_md) == (18, 22), _lowest_run(_md)
assert _peaks(_td) == [11, 19, 26], _peaks(_td)
